from pathlib import Path
import pandas as pd,numpy as np,duckdb,json
R=Path('/Volumes/ext/fin_agent');P=Path(__file__).parent;w=pd.read_pickle(R/'outputs/b2连续两日全量回放_20261113/近期输入/2026-11/test_samples.pkl.gz')[['stk_code','symbol','d0_date']].drop_duplicates(['stk_code','d0_date']);w=w[w.stk_code.str.endswith(('.SH','.SZ'))].copy();w['qdc_symbol']=w.stk_code.str.replace('.SH','.XSHG',regex=False).str.replace('.SZ','.XSHE',regex=False);symbols=sorted(w.qdc_symbol.unique());con=duckdb.connect();con.execute('SET threads=2');files=sorted(Path('/Volumes/ext/minite_k_data/日线').glob('2026-??.parquet'));con.register('symbols',pd.DataFrame({'symbol':symbols}));raw=con.execute("SELECT d.symbol,CAST(to_timestamp((ts+28800000)/1000) AS DATE) date,d.open,d.high,d.low,d.close,d.volume,d.amount FROM read_parquet(?) d JOIN symbols s ON d.symbol=s.symbol",[[str(f) for f in files]]).df();events=con.execute("SELECT e.symbol,e.d,e.hfq_factor FROM read_parquet('/Volumes/ext/minite_k_data/复权因子/all.parquet') e JOIN symbols s ON e.symbol=s.symbol ORDER BY e.symbol,e.d").df();con.close();raw['date']=pd.to_datetime(raw.date);raw['preclose']=np.nan
live=pd.read_pickle(R/'outputs/b2_d0_live_rebuild_20261112/daily_source.pkl.gz');live=live[live.stk_code.isin(set(w.stk_code))].copy();live['symbol']=live.stk_code.str.replace('.SH','.XSHG',regex=False).str.replace('.SZ','.XSHE',regex=False);live=live.rename(columns={'trade_date':'date'});live['date']=pd.to_datetime(live.date).astype('datetime64[ns]');live=live[['symbol','date','open','high','low','close','volume','amount','preclose']];daily=pd.concat([raw,live],ignore_index=True).sort_values(['symbol','date']);daily['date']=daily.date.astype('datetime64[ns]');daily=daily.drop_duplicates(['symbol','date'],keep='last');events['d']=pd.to_datetime(events.d).astype('datetime64[ns]');out=[];problem=0
for sym,g in daily.groupby('symbol'):
 e=events[events.symbol.eq(sym)].sort_values('d');g=g.sort_values('date').copy();g=pd.merge_asof(g,e[['d','hfq_factor']],left_on='date',right_on='d',direction='backward');
 for c in ['open','high','low','close','volume','amount','preclose','hfq_factor']:g[c]=pd.to_numeric(g[c],errors='coerce')
 g['adjustment_gap']=(g.preclose.notna() & (g.preclose-g.close.shift()).abs().gt(.011));g['ac']=g.close*g.hfq_factor;g['ah']=g.high*g.hfq_factor;g['al']=g.low*g.hfq_factor;g['av']=g.volume/g.hfq_factor;g['lr']=np.log(g.ac/g.ac.shift());indices={str(d.date()):i for i,d in enumerate(g.date)}
 for r in w[w.qdc_symbol.eq(sym)].itertuples():
  z={'qdc_symbol':sym,'d0_date':r.d0_date};i=indices.get(r.d0_date)
  if i is not None:
   for n in [20,60]:
    prior=g.iloc[max(0,i-n):i];window=g.iloc[max(0,i-n):i+1];valid=len(prior)==n and prior.ac.notna().all() and not window.adjustment_gap.any() and pd.notna(g.ac.iloc[i]);
    if not valid:
     if window.adjustment_gap.any():problem+=1
     continue
    cur=g.iloc[i];lo=prior.al.min();hi=prior.ah.max();z.update({f'prior_return_{n}':prior.ac.iloc[-1]/g.ac.iloc[i-n-1]-1 if i>=n+1 and pd.notna(g.ac.iloc[i-n-1]) else np.nan,f'prior_volatility_{n}':prior.lr.std(ddof=1),f'd0_volume_prior{n}':cur.av/prior.av.mean() if prior.av.mean()>0 else np.nan,f'd0_amount_prior{n}':cur.amount/prior.amount.mean() if prior.amount.mean()>0 else np.nan,f'd0_vs_ma{n}':cur.ac/prior.ac.mean()-1 if prior.ac.mean()>0 else np.nan,f'd0_position_{n}':(cur.ac-lo)/(hi-lo) if hi>lo else np.nan})
  out.append(z)
z=pd.DataFrame(out);assert not z.duplicated(['qdc_symbol','d0_date']).any();z.to_pickle(P/'十一月远期形态.pkl.gz',compression='gzip');(P/'十一月远期来源.json').write_text(json.dumps({'候选股票日':len(w),'计算股票日':len(z),'20日有效':int(z.prior_return_20.notna().sum()),'60日有效':int(z.prior_return_60.notna().sum()),'历史价格复权':'事件日asof，复权快照截至2026-09-30；10—11月检测到前收跳变时对应窗口设缺失','说明':'日线旧源到9月，10—11月使用KingdomAI日线；历史数据版本与跨源一致性未全面核验'},ensure_ascii=False,indent=2));print('完成',len(w),len(z),'20日',z.prior_return_20.notna().sum(),'60日',z.prior_return_60.notna().sum(),'跳变窗口',problem,flush=True)
